sysevent_script_action.script:
// Creates outbound webhook log entry for SLA breach (100%)
// event.parm1 = case sys_id, event.parm2 = task_sla sys_id
(function () {
    var enabled = gs.getProperty('x_2241073_securi_0.api.enabled', 'false');
    if (enabled != 'true') return;

    var caseId = event.parm1;
    var taskSlaId = event.parm2;
    if (!caseId) return;

    var caseGR = new GlideRecord('x_2241073_securi_0_sec_case');
    if (!caseGR.get(caseId)) return;

    // Only create webhooks for Torq-sourced cases
    if (caseGR.getValue('case_source') != 'torq') return;

    // Build payload
    var payload = {
        event_type: 'sla.breached',
        timestamp: new GlideDateTime().getValue(),
        case: {
            sys_id: caseGR.getUniqueValue(),
            number: caseGR.getValue('number'),
            short_description: caseGR.getValue('short_description'),
            severity: caseGR.getValue('severity'),
            state: caseGR.getValue('state'),
            assigned_to: caseGR.getDisplayValue('assigned_to'),
            sla_status: caseGR.getValue('sla_status'),
            torq_incident_id: caseGR.getValue('torq_incident_id'),
            api_url: gs.getProperty('glide.servlet.uri') + 'api/x_2241073_securi_0/security_case_inbound/case/' + caseGR.getValue('number'),
        },
        sla: {},
    };

    // Get SLA details
    if (taskSlaId) {
        var slaGR = new GlideRecord('task_sla');
        if (slaGR.get(taskSlaId)) {
            payload.sla = {
                sys_id: slaGR.getUniqueValue(),
                name: slaGR.getDisplayValue('sla'),
                stage: slaGR.getValue('stage'),
                percentage: slaGR.getValue('percentage'),
                has_breached: slaGR.getValue('has_breached'),
                planned_end_time: slaGR.getValue('planned_end_time'),
            };
        }
    }

    // Create webhook log entry
    var log = new GlideRecord('x_2241073_securi_0_webhook_log');
    log.initialize();
    log.setValue('case_id', caseId);
    log.setValue('direction', 'outbound');
    log.setValue('endpoint_url', gs.getProperty('x_2241073_securi_0.api.url', ''));
    log.setValue('http_method', 'POST');
    log.setValue('payload', JSON.stringify(payload));
    log.setValue('status', 'pending');
    log.insert();
})();
